import "./UserBoxs.css";

function UserBoxs({ key, name, username, email, phone, website }) {
  return (
    <div key={key} className="mainBoxes">
      <h2>{name}</h2>
      <h4>#{username}</h4>
      <button className="contactBtn">Contact me</button>
      <p>Email: {email}</p>
      <p>Phone: {phone}</p>
      <p>Webpage: {website}</p>
    </div>
  );
}

export default UserBoxs;
